INSERT INTO public.talks (id,"content",metadata,embedding) VALUES
	 ('21532a7d-3279-4c7e-96ab-858532e897fa'::uuid,'title:Bullseye or Backfire? Arrow in Kotlin Without the Poison, description:Kotlin’s Arrow library can spark strong opinions: some see it as a game-changer, others as unnecessary complexity. But what is Arrow really about, and how can it help us write better Kotlin? In this talk, we’ll look at where Arrow fits in everyday code, why it can lead to clearer and more reliable applications, and how it can be introduced without overwhelming teams. We’ll explore practical examples and share lessons learned from using Arrow in real projects. By the end, you’ll walk away with a balanced perspective on how to use Arrow as a tool to hit your coding goals, without the fear of it turning into something toxic.','{"id": "173abd2561534306881ef9a1d7ca742b", "room": "SUB 1", "title": "Bullseye or Backfire? Arrow in Kotlin Without the Poison", "endsAt": 1764258300000, "category": "[Presentation]", "dayIndex": 1, "speakers": "[Mehmet Akif Tütüncü]", "startsAt": 1764255600000, "phaseOfDay": "AFTERNOON", "conferenceDay": "2025-11-27", "durationMinutes": 45, "endsAtLocalDateTime": "2025-11-27T16:45:00", "startsAtLocalDateTime": "2025-11-27T16:00:00"}','[0.008212967,0.01795647,0.0062280525,-0.0003147336,0.009600015,0.00871859,-0.05310414,-0.009852827,0.008725423,0.015032052,0.010932402,-0.03760746,-0.017792484,-0.02533584,0.050070398,-0.029353498,-0.005175809,-0.040149245,0.004841004,0.027836626,-0.023477333,0.03162197,0.050261717,0.02515819,0.022042455,-0.031922612,-0.049195807,0.0071470574,0.04908648,-0.043920923,-0.005678016,-0.033726458,-0.014909063,-0.054252043,0.0018704656,-0.0047624274,0.0730831,-0.03727949,0.029872786,-0.05343211,-0.011827492,-0.03290653,-0.026292425,0.020265939,-0.009531688,0.023135694,-0.036022265,0.015414686,-0.007543357,-0.006952324,-0.07630816,0.017546505,0.018038463,0.073301755,-0.041187823,0.01567433,-0.016863229,0.05958159,0.019118037,0.012845572,0.03982127,-0.029107518,0.018284442,0.013392191,-0.06340793,0.0