	 ('da43f7fa-6c34-45e8-a5f8-d0b167e47274'::uuid,'title:Coding at the Speed of Thought: Kotlin, Compose, and the Power of Vim, description:Want to write Kotlin as fluidly as you think? This talk shows how using Vim inside IntelliJ supercharges your Kotlin development, especially with Jetpack Compose and coroutine-heavy code. You’ll learn how motions, macros, and modal editing can make you dramatically faster at navigating and refactoring Kotlin code. With live coding demos, you’ll see a real-world workflow in action. From building composables to wrangling Flow, all without even lifting your hands off the keyboard.','{"id": "4943c41c6b974f12980bf9c8afd40c46", "room": "SUB 7", "title": "Coding at the Speed of Thought: Kotlin, Compose, and the Power of Vim", "endsAt": 1764261900000, "category": "[Presentation]", "dayIndex": 1, "speakers": "[Oday Maleh]", "startsAt": 1764259200000, "phaseOfDay": "AFTERNOON", "conferenceDay": "2025-11-27", "durationMinutes": 45, "endsAtLocalDateTime": "2025-11-27T17:45:00", "startsAtLocalDateTime": "2025-11-27T17:00:00"}','[-0.01908842,0.03341998,-0.025930976,-0.015465888,0.017112494,-0.012093398,-0.016551428,0.03320043,0.006263197,0.011434756,0.013672919,0.039274577,0.007129189,0.011886048,0.023174439,-0.014904823,-0.025199153,-0.024613693,0.048032075,0.05264257,0.00042422945,-0.05796049,0.054447733,0.047202673,0.0011267046,-0.011544529,-0.09172199,0.016514838,0.029053427,-0.04983724,0.011050548,-0.018393187,0.014307166,-0.07967128,0.024369752,0.017990682,0.037030313,-0.014148605,0.00026147475,-0.005680787,-0.02174738,-0.041177318,0.011343278,0.017466208,-0.0037810926,0.02858994,-0.028760698,0.015441494,-0.017758938,0.040152766,-0.05854595,-0.0027565386,0.009275874,0.052154683,-0.038591538,-0.008861174,-0.006299788,0.007921999,-0.00044061927,-0.016551428,0.05971687,-0.031907544,0.02924858,0.004284222,-0.072694555,-0.004634888,-0.078110054,-0.010373611,-0.009263677,-0.0144169405,0.013331401,0.012831321,-0.040396705,0.018759098,-0.01867371