INSERT INTO public.talks (id,"content",metadata,embedding) VALUES
	 ('4aac5e43-1224-4ac3-9b70-c2efbe4c1518'::uuid,'title:Own your design: functional principles vs framework, description:Frameworks like Spring often tempt engineers into shortcuts that compromise clean design, such as primitive obsession or exception-driven error handling. In this session, we will explore how to reclaim control by applying Domain-Driven Design, hexagonal architecture, and functional programming principles—illustrated entirely with Kotlin, a language I have been using professionally since 2019.

We will focus on three key principles for a functional approach:
• Avoid primitive obsession by modeling rich domain types
• Apply interface segregation to reduce coupling and keep boundaries clean
• Treat errors as first-class citizens through functional error handling

Attendees will leave with practical strategies to keep domain logic clean and resilient, ensuring design—not the framework—remains at the core of the solution.','{"id": "8309e2d0cf1d479396a10bd2be574192", "room": "SUB 2", "title": "Own your design: functional principles vs framework", "endsAt": 1764242100000, "category": "[Presentation]", "dayIndex": 1, "speakers": "[Tiberiu Tofan]", "startsAt": 1764239400000, "phaseOfDay": "MORNING", "conferenceDay": "2025-11-27", "durationMinutes": 45, "endsAtLocalDateTime": "2025-11-27T12:15:00", "startsAtLocalDateTime": "2025-11-27T11:30:00"}','[-0.002910214,0.04939515,0.04964139,-0.03351286,0.07027605,-0.026765967,-0.05624054,0.03383297,0.009301605,0.015734548,0.065449804,-0.061903995,-0.004527684,-0.009849482,0.019834394,0.010563569,0.0005755791,-0.013112123,0.038979325,0.036172222,0.013284489,0.0021176387,0.042500515,0.018086111,0.018135358,0.0047831545,-0.024020424,0.022715367,0.033808347,-0.018159982,0.0035704372,-0.024180477,-0.006913105,-0.05628979,0.043953314,-0.0076949075,0.028292637,0.043904066,-0.010742092,0.008002704,-0.007971925,-0.07992855,-0.022124398,0.00025412432,-0.013653845,0.056930006,0.018578585,-0.0011873243,-0.011099135,0.008932249,-0.036319964,-0.033931464,0.06914336,0.03132135,-0.049345903,0.022678431,0.009344696,0.016103903,-0.0007941145,0.05564957,0.08002704,-0.029720811,0.021114826,0.029548446,-0.050158486,-0.0018513948,-0.048878055,-0.049616765,0.012902821,0.016768742,0.05343344,0.0021838148,-0.032478668,0.022518378,0.027972529,-0.021878162,0.008095043,-0.012459595,0.039053194,0.0034319288,-0.015722236,-0.010643597,0.024906877,-0.03531039,-0.037378784,-0.051020317,-0.07352638,0.0035211898,-0.052202255,-0.018911006,0.03501491,0.006075899,-0.014527986,-0.009246201,0.052596234,0.045356862,0.0173474,0.050059993,0.011320748,-0.005269473,0.07052229,-0.034891788,-0.023318648,0.008131978,0.021705795,-0.0190095,0.039176315,6.2088286e-05,-0.052054513,-0.018233852,-0.10745785,-0.020486923,0.0053033303,0.0266428